# compute orthogonal convex closure demo3 from manually transcribed 1/6 set
R=C=12
occ={(0,1),(1,1),(2,1),(3,1), (4,1),(4,2),(4,3),(4,4), (5,1),(5,2),(5,3),(5,4), (6,1),(6,2),(6,3),(7,1),(8,1), (9,0),(9,1),(9,2),(10,0),(10,1),(10,2), (11,0),(11,1),(11,2),(11,6),(11,7),(11,8),(11,9),(11,11)}
cur=set(occ)
for _ in range(30):
 old=len(cur)
 for r in range(R):
  xs=[c for rr,c in cur if rr==r]
  if xs: cur.update((r,c) for c in range(min(xs),max(xs)+1))
 for c in range(C):
  ys=[r for r,cc in cur if cc==c]
  if ys: cur.update((r,c) for r in range(min(ys),max(ys)+1))
 if len(cur)==old: break
print(len(cur), len(cur-occ),sorted(cur-occ))
